-- D1 Migration: Add ProductCategory table and seed categories

CREATE TABLE IF NOT EXISTS "ProductCategory" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "name" TEXT NOT NULL,
    "slug" TEXT NOT NULL,
    "description" TEXT,
    "imageUrl" TEXT NOT NULL,
    "bannerUrl" TEXT,
    "displayOrder" INTEGER NOT NULL DEFAULT 0,
    "isActive" BOOLEAN NOT NULL DEFAULT 1,
    "isHomepageVisible" BOOLEAN NOT NULL DEFAULT 1,
    "department" TEXT NOT NULL DEFAULT 'GROCERY',
    "metaTitle" TEXT,
    "metaDescription" TEXT,
    "parentId" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY ("parentId") REFERENCES "ProductCategory" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS "ProductCategory_slug_key" ON "ProductCategory"("slug");
CREATE INDEX IF NOT EXISTS "ProductCategory_parentId_idx" ON "ProductCategory"("parentId");
CREATE INDEX IF NOT EXISTS "ProductCategory_department_idx" ON "ProductCategory"("department");
CREATE INDEX IF NOT EXISTS "ProductCategory_isActive_isHomepageVisible_displayOrder_idx" ON "ProductCategory"("isActive", "isHomepageVisible", "displayOrder");

